INSERT INTO TB_EEP_ROW_MEMO_R (TARGET_CD, TARGET_SQ, CONTENT, EMPLY_ID)
SELECT 'EQP', EQP_SQ, CONCAT('[반납 ', GREATEST(#{END_DT}, IFNULL(DATE_FORMAT(START_DT, '%Y-%m-%d'), #{END_DT})), '] ', #{CONTENT}), #{UPDT_EMPLY_ID}
FROM TB_EEP_EQP_RENT_H WHERE STAFF_SQ = #{STAFF_SQ} AND OPEN_YN = 'Y'
